def min_Swaps(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        return -1
    # If the number of 1s differs, conversion is impossible
    if s1.count('1') != s2.count('1'):
        return -1

    a = b = 0  # a: '1'->'0' mismatches, b: '0'->'1' mismatches
    for x, y in zip(s1, s2):
        if x == '1' and y == '0':
            a += 1
        elif x == '0' and y == '1':
            b += 1

    # Total mismatches must be even for a valid conversion
    if (a + b) % 2 != 0:
        return -1

    # Each swap fixes one '1'->'0' and one '0'->'1' mismatch.
    # If counts match, answer is a (== b). If unequal, impossible (counts equal implies a == b),
    # so we can just return (a + b) // 2, which equals a.
    return (a + b) // 2


assert min_Swaps("1101", "1110") == 1
